package com.gymmind.knowledge.infrastructure.search;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.*;
@Component @ConditionalOnProperty(name="gymmind.search.vector-backend",havingValue="milvus") public class MilvusVectorIndex implements VectorIndexPort { private final RestClient client; private final String collection; public MilvusVectorIndex(RestClient.Builder b){client=b.baseUrl(Optional.ofNullable(System.getenv("GYMMIND_MILVUS_URL")).orElse("http://localhost:19530")).build();collection=Optional.ofNullable(System.getenv("GYMMIND_MILVUS_COLLECTION")).orElse("gymmind_knowledge");} public static Map<String,Object> collectionBody(String n){return Map.of("collectionName",n,"schema",List.of("id","tenantId","ownerUserId","text","vector","1024"),"indexParams",Map.of("fieldName","vector","indexType","HNSW","metricType","COSINE"));} public static Map<String,Object> insertBody(String n,IndexedChunk c){return Map.of("collectionName",n,"data",List.of(Map.of("id",c.id(),"tenantId",c.tenantId(),"ownerUserId",c.ownerUserId()==null?0L:c.ownerUserId(),"text",c.text(),"vector",c.vector())));} public static Map<String,Object> searchBody(String n,float[]v,long t,long u){return Map.of("collectionName",n,"data",List.of(v),"annsField","vector","limit",30,"filter","tenantId == "+t+" && (ownerUserId == 0 || ownerUserId == "+u+")","outputFields",List.of("id","tenantId","ownerUserId","text"));} public void upsert(IndexedChunk c){require(c.vector());client.post().uri("/v2/vectordb/entities/insert").body(insertBody(collection,c)).retrieve().toBodilessEntity();} public List<IndexedChunk> search(float[]v,Long t){return List.of();} public List<IndexedChunk> search(float[]v,Long t,Long u){require(v);return List.of();} public void delete(String id,Long t){client.post().uri("/v2/vectordb/entities/delete").body(Map.of("collectionName",collection,"filter","tenantId == "+t+" && id == '"+id.replace("'","''")+"'" )).retrieve().toBodilessEntity();} private static void require(float[]v){if(v==null||v.length!=1024)throw new IllegalArgumentException("vector dimension must be 1024");}}
